dp = array of amount + 1 filled with infinity
dp[0] = 0
for value from 1 to amount:
    for coin in coins:
        if coin <= value:
            dp[value] = min(dp[value], dp[value - coin] + 1)
return -1 if dp[amount] is infinity else dp[amount]
